INSERT INTO himnos (id, title, description, musical_note, paragraphs, chorus, filename)
VALUES
('0b78131d-a741-1d41-9a82-1f5e2a234988', $a$AQUELLA CRUZ$a$, $a$El cordero que sufrió Traicionado fue El peso de$a$, $a$A|La$a$, $a$[{"id": "fe7c1a78-21ba-4ef0-b672-a0b738fdbb7c", "paragraph": "El cordero que sufrió\nTraicionado fue\nEl peso de nuestra maldad\nFue puesto sobre Él", "chorusPos": [[0]]}, {"id": "3c8b2e54-23be-dd34-d1b4-dee64ffc4b4c", "paragraph": "En silencio soportó\nDolor y humillación\nObediente al Padre fue\nLa cruz por mí cargó", "chorusPos": [[1]]}, {"id": "ffb7f306-96ff-9772-adb6-0ddcd5d9648c", "paragraph": "Unigénito de Dios\nViniste a redimir\nY perdonar a todo aquel\nQue se acerca a ti", "chorusPos": [[1]]}, {"id": "7dd9cf4b-12d5-ea3c-5f29-b709d8be42af", "paragraph": "A la muerte Él venció\nLa tumba abierta está\nAleluya al Salvador\nJesús resucitó", "chorusPos": [[1]]}]$a$::jsonb, $a$[{"choir": "En aquella cruz me salvaste\nDerramaste allí tu amor\nMi alma cantará Aleluya\nGloria y honra a ti Señor", "id": "92da4e7e-bdea-5865-e5f4-fce74b7ab3e7"}]$a$::jsonb, $a$Aquella Cruz.json$a$),
('7be7efc9-3211-4a79-986f-bd88fe15bea1', $a$En casa de mi dios$a$, $a$Ropa blanca vestiré    /En casa d...$a$, $a$--$a$, $a$[{"paragraph": "Ropa blanca vestiré  \n /En casa de mi dios/ \n Allí feliz seré"}, {"paragraph": "una corona llevare   \n /En casa de mi dios/ \n Allí feliz seré"}, {"paragraph": "CON MI HERMANO ANDARÉ  \n /EN CASA DE MI DIOS/ \n ALLÍ FELIZ SERÉ"}, {"paragraph": "UNA ARPA TOCARE    \n /EN CASA DE MI DIOS/ \n ALLÍ FELIZ SERÉ"}, {"paragraph": "CALLES DE ORO ANDARÉ   \n /EN CASA DE MI DIOS/ \n ALLÍ FELIZ SERÉ"}, {"paragraph": "Aguas de vida tomare  \n /En casa de mi dios/  \n alli feliz sere"}, {"paragraph": "EN UN PALACIO HABITARE  \n /EN CASA DE  \n MI DIOS/ \n ALLÍ FELIZ SERÉ"}]$a$::jsonb, $a$[]$a$::jsonb, $a$En casa de mi dios.json$a$),
('17ce943a-93c2-ebab-12cc-f256accbae22', $a$EL PODER DE LA CRUZ$a$, $a$Oh, el ver aquel negro amanecer Rumbo al calvari$a$, $a$G|Sol$a$, $a$[{"id": "be49237e-f7ae-269b-0f19-57be4b9ea44a", "paragraph": "Oh, el ver aquel negro amanecer\nRumbo al calvario va Jesús\nGrande fue el dolor\ny la humillación\nCuando en la Cruz murió.", "chorusPos": [[1]]}, {"id": "a364db7c-7a4c-b5cf-d21f-94d4aec2ede8", "paragraph": "Oh, ver el dolor que tu faz mostró Cargando\nmi pecado atroz Todo mal pensar, toda\nmala acción Coronaron tu humillación.", "chorusPos": [[1]]}, {"id": "1aa9d0e5-f2ae-9bd6-fb3b-9bc0ad3ad54f", "paragraph": "La tierra tembló, todo oscureció\nSu rostro inclina su Creador\nVelo roto en dos, triunfante exclamo: \"Ya\ntodo terminó\"", "chorusPos": [[1]]}, {"id": "1fe5aaa6-d11b-2f2c-5654-581e47212950", "paragraph": "Oh mi nombre ver escrito\nen tu cruz\nPorque sufriste libre soy\nYa no moriré, vida me otorgó\nTu generoso amor.", "chorusPos": [[2]]}]$a$::jsonb, $a$[{"choir": "El poder de la Cruz:\nmi lugar Él tomó\nMi castigo sufrió,\nEn esa Cruz halle perdón", "id": "90f55883-b079-3449-eca9-2782139ac93f"}, {"choir": "/El poder de la Cruz:\nDios al hijo inmoló\nQue alto precio pagó,\nEn esa Cruz halle perdón./", "id": "1d1c471d-cbd4-a224-afea-e07bae90802e"}]$a$::jsonb, $a$El Poder de la Cruz.json$a$),
('16485f05-1d28-453e-895b-3f7c98776a22', $a$CON CRISTO EN LA FAMILIA$a$, $a$CON CRISTO EN LA FAMILIA    UN FE...$a$, $a$--$a$, $a$[{"paragraph": "CON CRISTO EN LA FAMILIA  \n UN FELIZ HOGAR  \n QUE FELICIDAD"}]$a$::jsonb, $a$[]$a$::jsonb, $a$CON CRISTO EN LA FAMILIA.json$a$),
('a1cd57df-f1a6-4b54-83c3-c6e0553c7dad', $a$En Cristo está mi salvación$a$, $a$En Cristo está mi salvación   Ver...$a$, $a$--$a$, $a$[{"paragraph": "En Cristo está mi salvación \n Versículo: Hechos 4:12"}, {"paragraph": "En Cristo está mi salvación; \n Él es mi fuerza, luz, canción. \n La Roca Eterna, fundación; \n Firme en prueba y tentación. \n Oh, alto amor, profunda paz; \n La lucha cesa y el temor. \n Mi esperanza y protección. \n En el amor de Cristo estoy."}, {"paragraph": "En Cristo está mi redención; \n Dios infinito se humilló. \n Su don de amor y libertad \n El mundo entero despreció. \n Allá en la cruz, mientras murió, \n El justo Dios se conformó, \n Y mi pecado Él cargó, \n Hoy en Su muerte vivo yo."}, {"paragraph": "Fue sepultado al morir, \n La luz del mundo se apagó. \n Mas con poder resucitó: \n De muerte Él se levantó. \n ¡Glorioso Rey! El Vencedor \n De mi pecado me libró. \n Pues Suyo soy y mío es Él. \n Dios con Su sangre me compró."}, {"paragraph": "Vivir sin culpa y sin temor, \n Es el poder de Cristo en mí. \n Desde nacer hasta morir, \n Cristo conduce mi existir. \n No hay poder ni voluntad \n Que de Él me pueda apartar, \n Hasta que vuelva o muera yo, \n En el poder de Cristo estoy."}]$a$::jsonb, $a$[]$a$::jsonb, $a$En Cristo está mi salvación.json$a$),
('d2e65938-1ea0-637d-f37e-ab83e0864274', $a$CORDERO$a$, $a$Cordero, que bajaste del cielo   a morir en la c$a$, $a$_$a$, $a$[{"id": "af3ffba5-526e-d52d-4ae9-bcb1121y5e32", "paragraph": "Cordero, que bajaste del cielo \n a morir en la cruz \n Para darme la luz \n y tu gran salvación, \n \n vertiste sangre inmaculada \n Con la cual mi maldad, \n al morir en la cruz, \n perdonaste Jesús. \n", "chorusPos": [[1]]}, {"id": "943c1bcd-32a0-0775-19e2-d70b7bf896d7", "paragraph": "Tú eres el que diste a mi vida \n esa paz sin igual, \n Que en el mundo falaz, \n no la pude encontrar. \n  \n Por eso mi alma alegre te canta, \n disfrutando el amor \n Que en la cruz de dolor \n me extendiste, Jesús.", "chorusPos": [[1]]}]$a$::jsonb, $a$[{"choir": "Hoy yo te alabo, Señor, \n con todo mi corazón, \n Cordero, porque eres mi Dios \n y mi buen Salvador \n que moriste por mí.", "id": "85fbe665-87b2-0c64-c00a-c23f83e534c1"}]$a$::jsonb, $a$CORDERO.json$a$),
('de002f37-3c87-f7e3-ada1-887bfe528bfe', $a$TODO LO PAGO$a$, $a$Puedo oír la voz de Cristo Que me llama hacia Él$a$, $a$C|Do$a$, $a$[{"id": "266dcbbe-35f0-76a1-c1eb-94621ad4737e", "paragraph": "Puedo oír la voz de Cristo\nQue me llama hacia Él,\nTodo cuanto necesito\nLo encuentro sólo en Él", "chorusPos": [[0]]}, {"id": "910a5168-f048-837b-5fd1-7b3ba0495bf6", "paragraph": "Buen pastor, refugio eterno,\nMi todo en todo es Él.\nDe la vida, Él es la fuente,\nMi esperanza en Él pondré.", "chorusPos": [[0]]}, {"id": "3cee88a4-fc6b-ad53-19c7-c9c8872dc197", "paragraph": "Siendo yo su enemigo\nDe mi tuvo compasión,\nRechazaba yo su gracia\nY Él abrió mi corazón.", "chorusPos": [[0]]}, {"id": "9cdc56ac-5803-5c01-2c63-0b75673e4128", "paragraph": "Nada bueno en mi yo encuentro\nMi virtud viene de Él\nY cuando en Él yo esté completo\n/ Para siempre cantaré /", "chorusPos": [[1]]}, {"id": "47c4eaa6-98e7-4e92-44de-9320ce148f5a", "paragraph": "Jesucristo es mi deleite\nGrande gozo tengo en Él\nNada más me satisface\n/ Cristo mi tesoro es /", "chorusPos": [[1], [2]]}]$a$::jsonb, $a$[{"choir": "/ Cantaré /\nEl cordero digno es\nSalvador pagó mi deuda\nSe lo debo todo a Él\n\n/ Cantaré /\nSiempre yo le alabaré\nEl mis manchas ha lavado\n/ Suyo siempre yo seré /", "id": "ae038f89-36a6-dfbc-3783-2f8989f70aef"}, {"choir": "Todo lo pago quien por mi murió\nY mis manchas él lavo\n\n/ Con sangre carmesí /", "id": "7bca1e3b-4115-3a17-93d4-09cb471d101c"}]$a$::jsonb, $a$TODO LO PAGO.json$a$),
('df5ed335-aea4-9ea0-beee-1164c79010cc', $a$VIVIR POR FE$a$, $a$Por fe, veremos a nuestro Dios En el plan que cr$a$, $a$A|La$a$, $a$[{"id": "74347f40-3670-ce6d-aaa5-a20738931c65", "paragraph": "Por fe, veremos a nuestro Dios\nEn el plan que creó en la eternidad.\nEn la vida de los fieles que llamó\nA vivir por fe y no por ver.", "chorusPos": [[0]]}, {"id": "a846a9d8-be44-b1be-5d59-26336cc8fb69", "paragraph": "Por fe, el justo vivirá\nPor la fe, caminamos junto a el\nComo viendo al invisible protector\nVivir por fe y no por ver", "chorusPos": [[1]]}, {"id": "95d408d3-9afb-5ee1-dbbe-076e9674afc2", "paragraph": "Por fe, profetas hablaron bien\nPor la fe, proclamaron la verdad\nEl Mesías prometido en edén\nEl que la muerte venció en la cruz", "chorusPos": [[0]]}, {"id": "94e202d4-ae52-df8d-20ac-c6fd215f4f46", "paragraph": "Por fe, la iglesia se moverá\nCon poder del espíritu de Dios\nY las fuerzas del infierno no podrán\nDañar la obra de nuestro Dios.", "chorusPos": [[1]]}, {"id": "e55c5c63-949e-92cc-f20b-e7ec65fbc3ed", "paragraph": "Por fe los montes se moverán\nSi la fe permanece en Jesús\nEl poder del evangelio librara\nA todo aquel que confía en él", "chorusPos": [[2]]}]$a$::jsonb, $a$[{"choir": "Sus promesas como rocas son,\nSus promesas cumple nuestro Dios\nNos movemos solo por la fe en Él\nVivir por fe y no por ver", "id": "791b4631-0c11-ad2a-2ab0-d470a12773aa"}, {"choir": "/Sus promesas como rocas son,\nSus promesas cumple nuestro Dios\nNos movemos solo por la fe en él\nVivir por fe y no por ver./\n/Vivir por fe y no por ver./", "id": "4cf7bb7c-b1d1-fb75-88c6-716f4100977c"}]$a$::jsonb, $a$VIVIR POR FE.json$a$),
('84772301-10de-4e2e-9116-2a013f6b96fa', $a$Cantemos a Jesús$a$, $a$Cantemos a Jesús   Cantemos a Jes...$a$, $a$--$a$, $a$[{"paragraph": "Cantemos a Jesús \n Cantemos a Jesús \n Señor de toda creación \n Dios de mi corazón"}, {"paragraph": "Cantemos a Jesús \n Cantemos a Jesús \n Victorioso mas que vencedor \n Rey sobre toda nación"}, {"paragraph": "/Digno de loor/ \n Señor de toda creación \n Dios de mi corazón \n /Digno de loor/ \n Victorioso mas que vencedor \n rey de mi corazón \n (Tu eres el Rey de mi corazón)"}]$a$::jsonb, $a$[]$a$::jsonb, $a$Cantemos a Jesús.json$a$),
('c28cae3f-7802-b276-35c3-7ccc908e9e19', $a$DE LA MANO SOBERANA$a$, $a$Cuan feroz llega la prueba acechando el corazón $a$, $a$A|La$a$, $a$[{"id": "e7d3fcda-bb18-63f5-6705-ba991eb9cd4c", "paragraph": "Cuan feroz llega la prueba acechando el corazón\nAmenaza con sus dudas, destruir mi convicción\nCuando todo es incierto; cuando es fácil tropezar\nEl refugio de mi alma, sé que no se moverá.", "chorusPos": [[2]]}, {"id": "5d0c62ab-3037-4dc1-df90-3e73c87f62d7", "paragraph": "Oh cuan altos Sus caminos; cuan supremo es Su plan\nTodo lo ha hecho hermoso en Su tiempo y voluntad\nAunque frágiles mis pasos; limitado mi entender\nSu palabra me asegura: todo obra para bien", "chorusPos": [[2]]}, {"id": "53fd7418-a420-a9f6-79a2-acc3ff1f81a3", "paragraph": "", "chorusPos": [[1], [2], [3]]}]$a$::jsonb, $a$[{"choir": "/Venga lo que venga, prevaleceré\nDios es mi esperanza\nSu promesa es fiel/", "id": "2bca7eb6-dec8-80dc-70b3-cecc60666e93"}, {"choir": "De la mano soberana de mi Dios me sostendré\nEn Su sabia providencia yo paciente esperaré\nPorque eterna es Su justicia y perfecto Su poder\nÉl ordena mis pasos y\nafirmando está mi fe", "id": "26b0a4fe-1c0d-d851-dfb6-e659b57df54c"}, {"choir": "Tú ordenas mis pasos\ny afirmando estás mi fe", "id": "c443420e-4700-e8b8-c62f-ffdb4e4b775a"}]$a$::jsonb, $a$De la Mano Soberana.json$a$),
('a5f199f0-d6c4-5f89-8665-2458b10b0067', $a$CUAN GRANDE ES DIOS$a$, $a$Cuan esplendor de un rey vestido de majestad la $a$, $a$E|Mi$a$, $a$[{"id": "b3eb6b4a-a754-673d-055d-a457912ff704", "paragraph": "Cuan esplendor de un rey\nvestido de majestad la tierra adorará, la tierra adorará.\nRodeado por su luz. tinieblas oscuridad tiembla con su voz.\nTiembla con su voz.", "chorusPos": [[1]]}, {"id": "505fb03e-bd38-ffdb-cf9c-b2d1c9432a75", "paragraph": "Perfecto solo es Él,\nel tiempo suyo es\nprincipio y final, principio y final.\nHermosa trinidad\nsu esencia en tres está.\nCordero vive hoy, cordero vive hoy.", "chorusPos": [[2], [3]]}]$a$::jsonb, $a$[{"choir": "Cuán grande es Dios, sin igual,\ncuán grande eres Dios,\ntodos cantarán\ncuán grande eres Dios.", "id": "452239b8-95da-ee5f-c017-5b1ff62f24b0"}, {"choir": "//Cuán grande es Dios, sin igual,\nCuán grande eres Dios, todos cantarán cuán grande eres Dios.//", "id": "2aade3ec-7557-512f-a8ef-d08475571341"}, {"choir": "Nombre sin igual\neres digno de adorar\nsiempre cantare\ncuán grande eres Dios.", "id": "551e0193-7fc5-5950-8d00-19d544193fc4"}]$a$::jsonb, $a$CUAN GRANDE ES DIOS.json$a$),
('17c90222-bf3c-456b-bf53-d5c9ad4efafc', $a$Fuiste a la cruz$a$, $a$//FUISTE A LA CRUZ   A MORIR  POR...$a$, $a$--$a$, $a$[{"paragraph": "//FUISTE A LA CRUZ \n A MORIR  POR MI \n HOY TE AGRADEZCO \n POR AMARME ASÍ"}, {"paragraph": "LE DISTE VALOR \n A MI VIDA SEÑOR \n POR ESO TE ADORO \n TE ADORO CRISTO.// \n FUISTE A LA CRUZ"}, {"paragraph": "TE AMO JESÚS \n ME CAMBIASTE  \n TU A MÍ. \n VEO EL ANTES Y AHORA \n  Y SOY FELIZ."}]$a$::jsonb, $a$[]$a$::jsonb, $a$Fuiste a la cruz.json$a$),
('88cdc5ce-ff16-12ed-aa06-aa19bd141424', $a$EN TERNURA$a$, $a$En ternura me busco perdido e infeliz Y en sus h$a$, $a$G|Sol$a$, $a$[{"id": "86c4b4b2-5959-cbf2-9d60-3af4f2b69ed7", "paragraph": "En ternura me busco\nperdido e infeliz\nY en sus hombros el me trajo\nDe vuelta a su redil\nMientras los ángeles cantaban\nLa corte celestial sonó", "chorusPos": [[1]]}, {"id": "ffdfe6ff-41e8-2283-c5ec-50ef7448893a", "paragraph": "Murió por mi mientras pecaba\nPobre y ciego fui\nMe hablo para decirme\nSoy suyo me compro\nJamás oi tan dulce voz\nHizo feliz mi corazón", "chorusPos": [[1]]}, {"id": "56532f48-17de-df8b-a7c1-7a25cb605c2c", "paragraph": "Su gracia yo meditare\nY te alabare\nCon asombro te adorare\nY te bendeciré\nParece la eternidad\nMuy corta para adorar", "chorusPos": [[1]]}]$a$::jsonb, $a$[{"choir": "Oh oh oh su amor me busco\nOh oh oh su sangre me compro\nOh la gracia que me trajo a su redil\nGracia que me trajo a su redil", "id": "b9e908c6-e7a3-0e45-f7b8-5c18a8942041"}]$a$::jsonb, $a$En Ternura.json$a$),
('02db95a5-811a-8b42-599b-bbdb7eb36b01', $a$BELLAS PALABRAS DE VIDA$a$, $a$Oh! cantádmelas otra vez, Bellas palabras de vid$a$, $a$A|La$a$, $a$[{"id": "aca3185f-e9fb-f229-27d2-50eabc4b9bb1", "paragraph": "Oh! cantádmelas otra vez,\nBellas palabras de vida;\nHallo en ellas mi gozo y luz,\nBellas palabras de vida.\nSí, de luz y vida son sostén y guía", "chorusPos": [[1]]}, {"id": "e26f1554-a1ea-08c1-e041-9abdd475e7a1", "paragraph": "Jesucristo a todos da\nBellas palabras de vida;\nOye su dulce voz, mortal,\nbellas palabras de vida.\nBondadoso te salva, y al cielo te llama.", "chorusPos": [[1]]}, {"id": "6a21ec9c-6142-26f1-592b-5775e825b28a", "paragraph": "Grato el cántico sonará,\nBellas palabras de vida;\nTus pecados perdonará,\nbellas palabras de vida.\nSólo Cristo redime, vida nueva te ofrece", "chorusPos": [[1]]}]$a$::jsonb, $a$[{"choir": "Qué bellas son, qué bellas son!\nBellas palabras de vida;\nQué bellas son, qué bellas son!\nBellas palabras de vida.", "id": "62c0c73a-b5e2-9619-45fc-e7ca22b22b22"}]$a$::jsonb, $a$Bellas Palabras de Vida.json$a$),
('eeaf4878-b6af-fd39-f0f6-2789d7fdec08', $a$LAVAME EN TU SANGRE$a$, $a$Que mi vida entera esté Consagrada a ti, Señor; $a$, $a$A|La$a$, $a$[{"id": "980ff8e8-a677-bc13-9b82-a7662582caf8", "paragraph": "Que mi vida entera esté\nConsagrada a ti, Señor;\nQue a mis manos pueda guiar\nEl impulso de tu amor.", "chorusPos": [[1]]}, {"id": "8911dc18-9c3a-78f8-0af9-5d0605cc6372", "paragraph": "Que mis pies tan solo en pos\nDe lo santo puedan ir,\nY que, a ti, Señor, mi voz\nSe complazca en bendecir.", "chorusPos": [[1]]}, {"id": "8e128386-a207-9c52-4c6b-3f975d6d3a6a", "paragraph": "Que mi tiempo todo esté\nConsagrado a tu loor.\nQue mis labios, al hablar,\nHablen solo de tu amor", "chorusPos": [[1]]}, {"id": "938178d4-2e63-dd3f-8ff9-fabd91a3e4ab", "paragraph": "Toma, oh Dios, mi voluntad,\nY hazla tuya, nada más.\nToma, sí, mi corazón,\nPor tu trono lo tendrás.", "chorusPos": [[1]]}, {"id": "437e0a11-9145-3328-8cbe-5b4118fff895", "paragraph": "Toma tú mi amor, que hoy\nA tus pies vengo a poner.\nToma todo lo que soy,\nTodo tuyo quiero ser", "chorusPos": [[2]]}]$a$::jsonb, $a$[{"choir": "Lávame en tu sangre, Salvador;\nLímpiame de toda mi maldad.\nTraigo a ti mi vida para ser, Señor,\nTuya por la eternidad.", "id": "15eac77b-989a-67ab-f917-32d595142671"}, {"choir": "Lávame en tu sangre, Salvador;\nLímpiame de toda mi maldad.\n/ Traigo a ti mi vida para ser, Señor,\nTuya por la eternidad. /", "id": "00a8b7d3-1a31-298f-2b18-f2569198f3a5"}]$a$::jsonb, $a$LAVAME EN TU SANGRE.json$a$),
('edc9bc55-6680-4264-ba96-c1590b475a02', $a$COMO RELÁMPAGO ASI SERA LA VENIDA DEL SEÑOR$a$, $a$COMO RELÁMPAGO ASI SERA LA VENIDA...$a$, $a$--$a$, $a$[{"paragraph": "COMO RELÁMPAGO ASI SERA LA VENIDA DEL SEÑOR \n MIRA A TU PUEBLO QUE CLAMANDO ESTA"}]$a$::jsonb, $a$[]$a$::jsonb, $a$COMO RELÁMPAGO ASI SERA LA VENIDA DEL SEÑOR.json$a$),
('8d5fc94b-8d12-44af-a1f6-01e1f78a795d', $a$El espiritu de Dios esta en este lugar$a$, $a$/El espíritu de dios esta en este...$a$, $a$--$a$, $a$[{"paragraph": "/El espíritu de dios esta en este lugar \n El espíritu de dios se mueve en este lugar/"}, {"paragraph": "Esta aquí para consolar \n Esta aquí para liberar \n Esta AQUÍ PARA GUIAR  \n EL ESPIRITU DE DIOS ESTA AQUI"}, {"paragraph": "/Muévete en mi/ SEÑOR \n TOCA MI MENTE MI CORAZON  \n LLENA MI VIDA DE TU AMOR \n MUEVETE EN MI DIOS ESPIRITU  \n MUEVETE EN MI"}]$a$::jsonb, $a$[]$a$::jsonb, $a$El espiritu de Dios esta en este lugar.json$a$),
('e420f3b4-f098-43af-b2b6-f80e87732d8f', $a$APRENDER A QUERER$a$, $a$ESTA VIDA QUE PAREWDCE TAN DIFIFC...$a$, $a$--$a$, $a$[{"paragraph": "ESTA VIDA QUE PAREWDCE TAN DIFIFCIL NOS AFLIHE PERNSAR DE NO PODER SALIR  \n QUE NO IMPORTA EL MOMNETO QU TODO TIEMPO TE TENGO  \n ES TU AMOR POR TI YO VIVIRE  \n APRENDER A QUERER APRENDER A CONFIAR NO IMPORTA LO QUE PÀSE AMIGO DE MI ALMA ME MUERO SI NO ESTAS \n HE APRENDIDO QUE NO HAY NADA IM POSIBLE  \n PERO NO IMPORTA EL MOMNETO"}, {"paragraph": "QUE NO IMPORTA EL MOMENTO QUE TODO TIEMPO TE TENGO  \n ES TU AMOR POR TI YO VIVIRE  \n APRENDER A QUERER  \n APRENDER A CONFIAR  \n NO IMPORTA LO QUE PÀSE AMIGO DE MI ALMA  \n ME MUERO SI NO ESTAS"}, {"paragraph": "ESTA VIDA QUE PAREWDCE TAN DIFIFCIL NOS AFLIHE PERNSAR DE NO PODER SALIR  \n QUE NO IMPORTA EL MOMNETO QU TODO TIEMPO TE TENGO  \n ES TU AMOR POR TI YO VIVIRE  \n APRENDER A QUERER APRENDER A CONFIAR NO IMPORTA LO QUE PÀSE AMIGO DE MI ALMA ME MUERO SI NO ESTAS \n PERO NO IMPORTA EL MOMNETO"}]$a$::jsonb, $a$[]$a$::jsonb, $a$APRENDER A QUERER.json$a$),
('242e94b0-9c22-1d34-e3ab-0f7fd9633bb6', $a$EL DIOS QUE ADORAMOS$a$, $a$El Dios que hizo los cielos y la tierra Con el p$a$, $a$F#|Fa#$a$, $a$[{"id": "9cc718eb-9b52-4da7-6996-b21a65ecc8c4", "paragraph": "El Dios que hizo\nlos cielos y la tierra\nCon el poder de Su palabra\nReina con autoridad", "chorusPos": [[0]]}, {"id": "db092dc2-aa87-08f3-cc3a-e4a4df9203ba", "paragraph": "El Dios que aún\nlos vientos le obedecen\nUna palabra es suficiente\nPara los muertos levanta", "chorusPos": [[1]]}, {"id": "37bde357-f6f6-7ddb-b7df-6cb43d31e0ad", "paragraph": "Tú eres el Dios que adoramos\nTodopoderoso y soberano\nGrande en misericordia y poder para salvar", "chorusPos": [[0]]}, {"id": "2787ebe7-481f-f438-3a48-474aa7422894", "paragraph": "Tú eres el Dios que adoramos\nQuien derrotó la muerte\ny el pecado\nGlorioso Redentor y Rey,\nTe adoramos", "chorusPos": [[0]]}, {"id": "1177243f-14cf-26ee-6342-727438b7dc02", "paragraph": "El Dios que descendió desde Su trono\nPara llevar sobre Sus hombros\nNuestra culpa y transgresión\nJesús, exaltado sobre todo\nNombre sobre todo nombre\nSolo en Él hay salvación.\n\nA Él sea la gloria y el poder\nTodo es de Él y para Él", "chorusPos": [[0]]}]$a$::jsonb, $a$[{"choir": "Nadie es como El, oh gran YO SOY", "id": "febb57d1-1957-1037-ed9e-885188f14850"}]$a$::jsonb, $a$El Dios que Adoramos.json$a$),
('12ffef4b-31fc-4a29-bc84-c141488937de', $a$DIOS PODEROSO$a$, $a$¿Quién sino el Señor   Las estrel...$a$, $a$--$a$, $a$[{"paragraph": "¿Quién sino el Señor \n Las estrellas creó \n Y su luz limitó?"}, {"paragraph": "¿Quién sino el Señor \n Sol y Luna formó \n Movimiento les dio?"}, {"paragraph": "¿Quién sino el Señor \n Hace la lluvia venir \n Truenos rugir? \n Tus obras grandes son"}, {"paragraph": "Dios poderoso \n Tú gobiernas la creación \n Con tu palabra, Señor \n Te exaltaremos \n Dios poderoso \n De ti canta la creación \n Llenas todo tú, Señor \n Te exaltaremos \n Por siempre y siempre, oh Dios"}, {"paragraph": "¿Quién sino el Señor \n Ha soñado en el plan \n Para al hombre salvar?"}, {"paragraph": "¿Quién sino el Señor \n Limpiará al pecador \n Con su sangre y amor?"}, {"paragraph": "¿Quién sino el Señor \n Puede dar vida y salvar \n Por una cruz? \n Tus planes grandes son"}, {"paragraph": "Dios poderoso \n Tú gobiernas la creación \n Con tu palabra, Señor \n Te exaltaremos \n Dios poderoso \n De ti canta la creación \n Llenas todo tú, Señor \n Te exaltaremos \n Por siempre y siempre, oh Dios"}, {"paragraph": "Todas las cosas \n Vienen de ti y por ti \n Oh gran yo soy \n Todo es tuyo \n Y para ti, oh Señor \n Oh gran yo soy"}, {"paragraph": "Dios poderoso \n Tú gobiernas la creación \n Con tu palabra, Señor \n Te exaltaremos \n Dios poderoso \n De ti canta la creación \n Llenas todo tú, Señor \n Te exaltaremos \n Por siempre y siempre, oh Dios \n *"}]$a$::jsonb, $a$[]$a$::jsonb, $a$DIOS PODEROSO.json$a$),
('d2e65938-1ea0-637d-f37e-ab83e0864275', $a$SU GRACIA ES MAYOR$a$, $a$¿Qué amor mis pecados decide olvidar?   Lanzados$a$, $a$E$a$, $a$[{"id": "af3ffba5-526e-d52d-4ae9-acb1121y5e32", "paragraph": "¿Qué amor mis pecados decide olvidar? \n Lanzados al mar no los quiere contar. \n Él siendo omnisciente olvida mi error, \n mis faltas son muchas, Su gracia es mayor.", "chorusPos": [[1]]}, {"id": "943c1bcd-32a0-0775-19e2-a70b7bf896d7", "paragraph": "Paciente me aguarda en mi desviar, \n Un padre que tierno me llama al hogar. \n Recibe al débil y vil pecador, \n mis faltas son muchas, Su gracia es mayor.", "chorusPos": [[1]]}, {"id": "943c1bcd-32a0-0775-19e2-b70b7bf896d7", "paragraph": "Que grandes riquezas, Él nos otorgó, \n Su sangre fue el pago, su vida entregó. \n Pagó esa deuda y la canceló, \n mis faltas son muchas, Su gracia es mayor.", "chorusPos": [[1, 2], [2, 2]]}]$a$::jsonb, $a$[{"choir": "Gloria a Dios, \n Su gracia es mayor, \n Sus misericordias hoy nuevas son, \n mis faltas son muchas, Su gracia es mayor", "id": "85fbe665-87b2-0c64-c00a-a23f83e534f1"}, {"choir": "mis faltas son muchas, Su gracia es mayor.", "id": "85fbe665-87b2-0c64-c00a-t23f83e534f1"}]$a$::jsonb, $a$SU GRACIA ES MAYOR.json$a$),
('fc761b89-4cf1-4b9a-8342-a8924539adbf', $a$al taller del maestro$a$, $a$Hay como me duele estar despierto...$a$, $a$--$a$, $a$[{"paragraph": "Hay como me duele estar despierto y no poder cantar  \n Como expresarte sin palabras, me muero siu no estas  \n El tiempo pasa y todo cambia, hoy lloro  de soledad; \n El sueño que llevo en el alma de repente ya no está \n Que la sonrisa se a marchado// mis lagrimas caerán.//"}, {"paragraph": "Al taller del maestro vengo, pues el me curara  \n Me tomara entre sus brazos y cada herida sanará \n Las herramientas del maestro, mi alma el remendará  \n Martillo en mano y mucho fuego, aunque me duele ayudara.....  \n A conocerlo y a entenderlo, a saber que nada merezco,  \n amar es mas que un pretexto, es una entrega, es un negar"}, {"paragraph": "Mas que aquel sentimiento, es la decisión de amar.... \n Al taller del maestro vengo, ahí el sol se pondrá \n Al taller del maestro vengo, no importa el tiempo allí he de estar  \n Al taller del maestro vengo.... \n Ay de aquellos días que hizo frio, el sol no apareció,  \n Cuando el talento no lo es todo y el silencio vale mas"}, {"paragraph": "Hay como me duele estar despierto y no poder cantar  \n Como expresarte sin palabras, me muero siu no estas  \n El tiempo pasa y todo cambia, hoy lloro  de soledad; \n El sueño que llevo en el alma de repente ya no está \n Que la sonrisa se a marchado// mis lagrimas caerán.//"}]$a$::jsonb, $a$[]$a$::jsonb, $a$al taller del maestro.json$a$),
('e4f46615-fdb2-31c2-b1fc-d4977bc9835d', $a$MARAVILLOSO ES EL GRAN AMOR$a$, $a$Maravilloso es el gran amor que Cristo el Salvad$a$, $a$_$a$, $a$[{"id": "72e778f9-b973-0fdc-9293-839f5a697b27", "paragraph": "Maravilloso es el gran amor que Cristo el Salvador\nderramó en mí; Siendo rebelde y pecador,\nyo de su muerte causa fui. ¡Grande, sublime,\ninmensurable amor! Por mí murió el Salvador.", "chorusPos": [[1]]}, {"id": "f77d4c2c-f56b-c515-a55f-d8c1650d52b7", "paragraph": "El su celeste hogar abandonó, dejando posición,\ngloria y honor; De todo ello se despojó.\npor rescatar al pecador. Misericordia inmensa\nél mostró; su gran amor me alcanzó.", "chorusPos": [[1]]}, {"id": "e8b1c2de-e4a3-c382-394a-efac3a685771", "paragraph": "¡Grande misterio! Dios el inmortal muriendo en la\ncruz entregó su ser; ni mente humana ni angelical\njamás lo puede comprender. Inexplicable\nes el infinito amor que demostró mi Salvador.", "chorusPos": [[1]]}, {"id": "501b7168-aa9e-1d8e-06c9-64c75841295c", "paragraph": "En vil prisión mi alma padeció, atada en pecado\ny oscuridad; pronto en mi celda resplandeció\nla clara luz de su verdad. Cristo las férreas\ncadenas destruyó; Quedó ya libre, ¡Gloria a Dios!", "chorusPos": [[1]]}, {"id": "088df862-22ea-4219-ae28-2a82d85bff65", "paragraph": "Hoy ya no temo la condenación; Jesús\nes mi Señor, y yo suyo soy.\nVivo en élque es mi salvación,\nvestido en su justicia voy.\nLibre acceso al Padre gozo ya\ny entrada al trono celestial.", "chorusPos": [[1]]}]$a$::jsonb, $a$[{"choir": "¡Oh, maravilla de su amor,\npor mí murió el Salvador!", "id": "45ec4505-9d59-123c-838e-4ed71fd7fcd9"}]$a$::jsonb, $a$MARAVILLOSO ES EL GRAN AMOR.json$a$),
('1ebc4cab-a5ad-44cb-9f4a-fd4da9c48a26', $a$cena del señor$a$, $a$ÉL HA SIDO    FIEL...$a$, $a$--$a$, $a$[{"paragraph": "ÉL HA SIDO  \n FIEL"}, {"paragraph": "Día a día Tú has sido fiel, no has cambiado y no cambiarás     \n Maravillado estoy con tu amor porque me amaste siendo un pecador"}, {"paragraph": "Cuando recuerdo mi vida sin ti, sin esperanza en sombras viví     \n Más hoy reboso en gracia y perdón, porque adoptaste a un vil pecador"}, {"paragraph": "Te alabaré, te glorificaré             \n  Porque agradecido estoy  \n por tu inmenso amor  \n Te alabaré, te glorificaré         \n Porque tu hijo soy, te alabaré"}, {"paragraph": "Cuando en prueba te exaltaré,  \n y cuando duela en ti confiaré   \n Porque conozco tu inmensa bondad y sé que nunca me abandonarás"}, {"paragraph": "Te alabaré, te glorificaré             \n  Porque agradecido estoy  \n por tu inmenso amor  \n Te alabaré, te glorificaré         \n Porque tu hijo soy, te alabaré"}, {"paragraph": "Toda mi vida la pongo a tus pies, has lo que quieras con ella mi Rey                                                             \n Hasta que vuelvas con fe cantaré, \"Día a día tú has sido fiel\""}, {"paragraph": "Te alabaré, te glorificaré             \n  Porque agradecido estoy  \n por tu inmenso amor  \n Te alabaré, te glorificaré         \n Porque tu hijo soy, te alabaré"}]$a$::jsonb, $a$[]$a$::jsonb, $a$cena del señor.json$a$),
('dab8372e-87b2-7802-cf4e-c2c7ba899ac4', $a$TU NOMBRE LEVANTARE$a$, $a$//Tú nombre levantaré, me deleito en adorarte. T$a$, $a$G|Sol$a$, $a$[{"id": "303e50ea-904f-017b-f73f-50f8ed430502", "paragraph": "//Tú nombre levantaré,\nme deleito en adorarte.\nTe agradezco que en mi vida estés,\nque vinieras a salvarme//.", "chorusPos": [[1]]}]$a$::jsonb, $a$[{"choir": "//Dejaste el trono para,\nmostrarnos la luz\nDe Tú trono a la cruz,\ny mi deuda pagar.\nDe la cruz a morir,\nde la muerte a tú trono;\nTú nombre levantaré//.", "id": "663e9947-17f3-73ad-9143-5b3d3862b13e"}]$a$::jsonb, $a$TU NOMBRE LEVANTARE.json$a$),
('68ff5d82-7808-41ba-8010-0aaa49d51d70', $a$HE DECIDIDO SEGUIR A CRISTO$a$, $a$// He decidido seguir a Cristo. // / No vuelvo a$a$, $a$C|Do$a$, $a$[{"id": "3883c6e8-cc1a-d3cb-22b3-b3d03125a637", "paragraph": "\n// He decidido seguir a Cristo. //\n/ No vuelvo atrás; no vuelvo atrás. /", "chorusPos": [[0]]}, {"id": "17529ab3-ef32-bf8e-20c2-3a5d2e93cfda", "paragraph": "// El Rey de gloria me ha transformado. //\n/ No vuelvo atrás; no vuelvo atrás. /", "chorusPos": [[0]]}, {"id": "4cc7a4c6-471f-531f-8828-14c821295c11", "paragraph": "// En mis tristezas me da consuelo. //\n/ No vuelvo atrás; no vuelvo atrás. /", "chorusPos": [[0]]}, {"id": "74ef6925-609a-5ca9-141d-5ab3897150c0", "paragraph": "// La cruz delante, el mundo atrás. //\n/ No vuelvo atrás; no vuelvo atrás. /", "chorusPos": [[0]]}]$a$::jsonb, $a$[]$a$::jsonb, $a$He Decidido Seguir a Cristo.json$a$),
('41738fef-e7cb-4a73-8441-c4b05bfcb3b8', $a$EN LA CASA DE MI PADRE$a$, $a$EN LA CASA DE MI PADRE   /HAY LUG...$a$, $a$--$a$, $a$[{"paragraph": "EN LA CASA DE MI PADRE \n /HAY LUGAR PARA TODOS/"}, {"paragraph": "PARA EL RICO  \n PARA EL POBRE  \n HAY LUGAR PARA TODOS"}, {"paragraph": "PARA EL NIÑO  \n PARA EL ANCIANO  \n /HAY LUGAR PARA TODOS/"}, {"paragraph": "PARA EL NEGRO  \n PAR EL BLANCO  \n /HAY LUGAR PARA TODOS/"}, {"paragraph": "PARA EL BLANCO \n PARA EL NEGRO \n /HAY LUGAR PARA TODOS/"}, {"paragraph": "PARA EL ALTO  \n PAR EL BAJO  \n /HAY LUGAR PARA TODOS/"}, {"paragraph": "PARA EL ALTO PARA EL BAJO HAY LUGAR PARA TODOS"}, {"paragraph": "EN ALACASA DEMI PADRE HAY LUGAR PARA TODO S \n PARA EL RICO  \n PARA EL POBRTE  \n HAY LUGAR PARA TODO  \n PARA EL NIÑO PAR EL VIEJO HAY LUGAR PARA TODOS \n PARA EL NEGRO  \n PAR EL BLANCO HAY LUGAR PARA TODOS \n HAY LUGAR PARA TODO PARA EL ALTO PARA EL BAJO HAY LUGAR PARA TODOS"}]$a$::jsonb, $a$[]$a$::jsonb, $a$EN LA CASA DE MI PADRE.json$a$),
('059aa4cd-4be7-481b-b0e9-4e3073fe5099', $a$EL SEÑOR YA VIENE PRONTO$a$, $a$/EL SEÑOR YA VIENE PRONTO Y SU PU...$a$, $a$--$a$, $a$[{"paragraph": "/EL SEÑOR YA VIENE PRONTO Y SU PUEBLO YA ESTA LISTO/ \n /TENGO PAZ TENGO AMOR \n CON MI SALVADOR/"}, {"paragraph": "/LLEVAREMOS SU PALABRA \n TODOS JUNTOS SIN NINGUN TEMOR/  \n /TENGO PAZ TENGO AMOR \n CON MI SALVADOR/"}]$a$::jsonb, $a$[]$a$::jsonb, $a$EL SEÑOR YA VIENE PRONTO.json$a$),
('9c70711b-f4da-406b-aff8-4416c7ff03c6', $a$CUANDO ESTABA YO$a$, $a$/Cuando estaba yo    lejos del Se...$a$, $a$--$a$, $a$[{"paragraph": "/Cuando estaba yo  \n lejos del Señor/ \n /Cayó la buena semilla  \n en mi corazón/"}, {"paragraph": "/Bendito Señor, bendito Jesús/ \n /La honra y la gloria sean para ti/ \n /Esa semilla fue  \n la palabra de Dios/ \n /Que cambió mi vida para  \n la gloria de Dios/"}]$a$::jsonb, $a$[]$a$::jsonb, $a$CUANDO ESTABA YO.json$a$),
('6c76749f-5f1b-4ba2-a470-a7bfe9ceb8eb', $a$ERES TODO PODEROSO$a$, $a$La única razón de mi adoración   ...$a$, $a$--$a$, $a$[{"paragraph": "La única razón de mi adoración \n Eres tu mi Jesús \n Mi único motivo para vivir      \n  eres tu mi Señor."}, {"paragraph": "Mi única verdad esta en ti  \n Eres mi luz y mi salvación \n Mi único amor eres tu Señor  \n Y por siempre te alabare."}, {"paragraph": "Eres Todo poderoso  \n Eres grande y majestuoso  \n Eres fuerte invencible  \n Y no hay nadie como tu."}, {"paragraph": "Tu eres Todo poderoso  \n Eres grande y majestuoso  \n Eres fuerte invencible  \n Y no hay nadie como tu."}, {"paragraph": "No hay nadie mas  \n que este con vos  \n ehhhehhh a ti a ti OOOOHOOOOO"}]$a$::jsonb, $a$[]$a$::jsonb, $a$ERES TODO PODEROSO.json$a$)
